package com.fintrack.khmtomnenh.orderitem.entity; import com.fasterxml.jackson.annotation.*; import com.fintrack.khmtomnenh.order.entity.Order; import com.fintrack.khmtomnenh.product.entity.Product; import jakarta.persistence.*; import lombok.*; import java.math.*;
@Entity @Table(name="order_items") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class OrderItem {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @JsonBackReference @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="order_id") private Order order; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="product_id") private Product product; @Column(nullable=false) private Integer quantity; @Column(name="unit_price",nullable=false,precision=19,scale=2) private BigDecimal unitPrice;}
